def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate a three-line repeated palette, horizontal or vertical.
    palette = None
    excluded = set()
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2]:
            cols = [c for c, v in enumerate(grid[r]) if v]
            if cols:
                palette = [grid[r][c] for c in cols]
                excluded = {(rr, c) for rr in range(r, r + 3) for c in cols}
                break

    if palette is None:
        for c in range(w - 2):
            if all(grid[r][c] == grid[r][c + 1] == grid[r][c + 2]
                   for r in range(h)):
                rows = [r for r in range(h) if grid[r][c]]
                if rows:
                    palette = [grid[r][c] for r in rows]
                    excluded = {(r, cc) for r in rows for cc in range(c, c + 3)}
                    break

    if not palette or 1 not in palette:
        return [row[:] for row in grid]

    # Use the color-1 shape as the template and keep its position as the anchor.
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == 1 and (r, c) not in excluded]
    if not cells:
        return [row[:] for row in grid]

    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    shape = [(r - min_r, c - min_c) for r, c in cells]
    shape_h = max(dr for dr, dc in shape) + 1

    out = [[0] * w for _ in range(h)]
    anchor_index = palette.index(1)
    for i, color in enumerate(palette):
        row_offset = min_r + (i - anchor_index) * shape_h
        for dr, dc in shape:
            rr, cc = row_offset + dr, min_c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    return out
